async function terminalCheckSaveNotes(notes){return terminalCheckMutation('notes',{id:terminalCheck.id,revision:terminalCheck.revision,notes})}
async function terminalCheckRefresh(){if(terminalCheckDirty()&&!confirm('Refresh and discard unsaved notes or tally?'))return;return terminalCheckMutation('refresh',{id:terminalCheck.id,revision:terminalCheck.revision})}
async function terminalCheckFinish(){if(terminalCheckDirty()&&!confirm('Finish and discard unsaved notes or tally?'))return;return terminalCheckMutation('finish',{id:terminalCheck.id,revision:terminalCheck.revision,review_fingerprint:terminalCheck.review_fingerprint})}
async function terminalCheckCancel(reason){if((!terminalCheck?.can_edit&&!terminalCheckManager())||terminalCheck.state!=='draft'||terminalCheckBusy)return;if(terminalCheckDirty()&&!confirm('Cancel and discard unsaved notes or tally?'))return;if(!confirm('Cancel this shelf check? This keeps a cancelled read-only history record.'))return;const note=prompt('Reason for cancellation');if(!note?.trim())return;return terminalCheckMutation('cancel',{id:terminalCheck.id,revision:terminalCheck.revision,confirmed:true,reason:note.trim()})}

